from fractions import Fraction

def bigger(a, b, c, d):
    left = a * d    # left top times right bottom
    right = c * b   # right top times left bottom
    if left > right:
        return 'L'
    if left < right:
        return 'R'
    return 'E'


def order_fractions(pairs):
    return sorted(pairs, key=lambda p: Fraction(p[0], p[1]))
